import re
def tokens(s):
    return set(re.findall(r"\w+", s.casefold()))
def score(question, passage):
    return len(tokens(question) & tokens(passage))
assert score("refund time", "refund time is five days") == 2

def check_citations(answer, passages):
    allowed = {p["id"] for p in passages}
    if answer["status"] == "answered":
        if not answer["citations"] or not set(answer["citations"]) <= allowed:
            raise ValueError("Missing or unknown citation")
    return answer

def recall_at_k(relevant, retrieved):
    if not relevant:
        return None  # Evaluate unanswerable questions separately.
    return len(set(relevant) & set(retrieved)) / len(set(relevant))
assert recall_at_k(["a", "b"], ["a", "c"]) == 0.5
